descriptor.controllerScript:
self.onInit = function () {
    var COUNT = 7;        // pumps (sp1 ... sp7)
    var MIN = 0;          // ml/perc
    var MAX = 100;       // ml/perc  <-- placeholder, set your real maximum
    var UNIT = 'ml/perc';
    var PREFIX = 'sp';    // shared attribute key prefix

    var root = self.ctx.$container[0];
    var http = self.ctx.http;
    var openBtn = root.querySelector('.ao-open');
    var overlay = null;

    function el(tag, css, text) {
        var e = document.createElement(tag);
        if (css) { e.style.cssText = css; }
        if (text) { e.textContent = text; }
        return e;
    }

    function errText(e) {
        return (e && e.error && e.error.message) ? e.error.message : 'Ismeretlen hiba';
    }

    // the device comes from the widget's data source (alias)
    function getTarget() {
        var ds = self.ctx.datasources && self.ctx.datasources[0];
        if (!ds || !ds.entityId) { return null; }
        return { type: ds.entityType || 'DEVICE', id: ds.entityId, name: ds.entityName || '' };
    }

    function close() {
        if (overlay && overlay.parentNode) { overlay.parentNode.removeChild(overlay); }
        overlay = null;
    }

    function openDialog() {
        if (overlay) { return; }
        var t = getTarget();

        var INPUT = 'box-sizing:border-box;width:100%;margin-top:2px;padding:8px;border:none;' +
                    'border-radius:8px;font-size:14px;color:#1b1f3b;background:#ffffff;';
        var LABEL = 'display:block;font-size:12px;margin-top:10px;color:black;';
        var BTN = 'flex:1;padding:10px;border:none;border-radius:12px;font-size:15px;' +
                  'font-weight:600;color:black;cursor:pointer;';

        overlay = el('div', 'position:fixed;top:0;left:0;right:0;bottom:0;z-index:10000;' +
                            'background:rgba(0,0,0,0.4);display:flex;align-items:center;justify-content:center;');
        var box = el('div', 'box-sizing:border-box;width:300px;max-width:90vw;padding:18px;' +
                            'background:#A7C7E7;color:#ffffff;border-radius:20px;font-family:inherit;' +
                            'box-shadow:0 8px 30px rgba(0,0,0,0.35);');

        box.appendChild(el('div', 'text-align:center;font-size:16px;font-weight:600;color:black;', 'Átfolyás beállítása'));
        if (t && t.name) { box.appendChild(el('div', 'text-align:center;font-size:12px;opacity:0.0;', t.name)); }

        // pump selector
        var l1 = el('label', LABEL, 'Pumpa');
        var select = el('select', INPUT);
        for (var i = 1; i <= COUNT; i++) {
            var o = document.createElement('option');
            o.value = String(i);
            o.textContent = 'Pumpa #' + i;
            select.appendChild(o);
        }
        l1.appendChild(select);
        box.appendChild(l1);

        // value
        var l2 = el('label', LABEL, 'Érték (' + UNIT + ')');
        var input = el('input', INPUT);
        input.type = 'text';
        input.setAttribute('inputmode', 'decimal');
        l2.appendChild(input);
        box.appendChild(l2);

        var hint = el('div', 'margin-top:6px;font-size:12px;min-height:16px;opacity:0.9;');
        var msg = el('div', 'margin-top:8px;font-size:13px;font-weight:600;text-align:center;min-height:18px;');
        box.appendChild(hint);
        box.appendChild(msg);

        function setMsg(text, ok) {
            msg.textContent = text;
            msg.style.color = ok ? '#1b5e20' : '#b71c1c';
        }

        // buttons
        var row = el('div', 'display:flex;gap:8px;margin-top:12px;');
        var sendBtn = el('button', BTN + 'background:#6E9FCB;', 'Küldés');
        var cancelBtn = el('button', BTN + 'background:#8d9db0;', 'Bezárás');
        row.appendChild(sendBtn);
        row.appendChild(cancelBtn);
        box.appendChild(row);

        overlay.appendChild(box);
        document.body.appendChild(overlay);

        // current value of the selected pump
        function loadCurrent() {
            if (!t) { return; }
            var key = PREFIX + select.value;
            hint.textContent = '';
            http.get('/api/plugins/telemetry/' + t.type + '/' + t.id +
                     '/values/attributes/SHARED_SCOPE?keys=' + key).subscribe(
                function (arr) {
                    var item = (arr || []).filter(function (a) { return a.key === key; })[0];
                    if (item) {
                        hint.textContent = 'Jelenlegi érték: ' + item.value + ' ' + UNIT;
                        input.value = String(item.value);
                    } else {
                        hint.textContent = 'Még nincs beállított érték.';
                        input.value = '';
                    }
                },
                function () { hint.textContent = ''; }
            );
        }

        if (!t) {
            setMsg('Nincs eszköz kiválasztva: adj a widgethez adatforrást (alias).', false);
            sendBtn.disabled = true;
        } else {
            loadCurrent();
        }

        select.addEventListener('change', loadCurrent);
        cancelBtn.addEventListener('click', close);
        overlay.addEventListener('click', function (ev) { if (ev.target === overlay) { close(); } });

        sendBtn.addEventListener('click', function () {
            var v = parseFloat(String(input.value).replace(',', '.'));
            if (isNaN(v) || v < MIN || v > MAX) {
                setMsg('Az érték ' + MIN + ' és ' + MAX + ' ' + UNIT + ' között legyen.', false);
                return;
            }
            var n = select.value;
            var body = {};
            body[PREFIX + n] = v;

            sendBtn.disabled = true;
            setMsg('Küldés...', true);
            http.post('/api/plugins/telemetry/' + t.type + '/' + t.id + '/attributes/SHARED_SCOPE', body).subscribe(
                function () {
                    setMsg('Elküldve: Pumpa #' + n + ' = ' + v + ' ' + UNIT, true);
                    hint.textContent = 'Jelenlegi érték: ' + v + ' ' + UNIT;
                    sendBtn.disabled = false;
                },
                function (e) {
                    setMsg('Hiba: ' + errText(e), false);
                    sendBtn.disabled = false;
                }
            );
        });
    }

    openBtn.addEventListener('click', openDialog);

    self.ctx.closeAoDialog = close;
};

self.onDestroy = function () {
    if (self.ctx.closeAoDialog) { self.ctx.closeAoDialog(); }
};

